Bash(cd /d/projects/petrov && cp src/data/portfolio.json .tmp-portfolio.bak && node -e "
const fs=require\('fs'\),path=require\('path'\);
const file='src/data/portfolio.json';
const data=JSON.parse\(fs.readFileSync\(file,'utf8'\)\);
const seenIds=new Set\(\), seenSlugs=new Set\(\);
data.items=data.items.filter\(it=>{
  if\(seenSlugs.has\(it.slug\)||seenIds.has\(it.id\)\) return false;
  seenIds.add\(it.id\); seenSlugs.add\(it.slug\); return true;
}\);
const year=s=>\(s.match\(/^\\d{4}/\)||['']\)[0];
const items=data.items.map\(it=>\({...it, _y: year\(it.slug\)||year\(it.timeText\)||'0'}\)\);
items.sort\(\(a,b\)=> b._y - a._y || String\(a.timeText\).localeCompare\(String\(b.timeText\)\)\);
const withYear=y=>{ const last=items.filter\(i=>i._y===y\).pop\(\); return last; };
const last2024=items.filter\(i=>i._y==='2024'\).pop\(\);
const insertPoint=items.indexOf\(last2024\)+1;
items.splice\(insertPoint,0,{
  id:'020', slug:'bitexchange', title:{ru:'Bitcoin exchange service',en:'Bitcoin exchange service'},
  description:{ru:'Web service for exchanging currencies and cryptocurrencies',en:'Web service for exchanging currencies and cryptocurrencies'},
  features:[], timeText:'2021',
  previewImage:'/static/portfolio/2021-bitexchange/001.png',
  images:['/static/portfolio/2021-bitexchange/001.png'],
  tags:['bitexchange','exchange','vue','javascript','html','css']
}\);
items.forEach\(i=>delete i._y\);
data.items=items;
fs.writeFileSync\(file, JSON.stringify\(data,null,2\)+'\\n'\);
console.log\('items now', data.items.length\);
console.log\(items.map\(i=>i.slug\).join\(', '\)\);
")

